mapper.select:
SELECT u.id, u.username, u.display_name, u.bio, u.avatar_key, f.created_at AS followed_at
FROM follows f JOIN users u ON u.id = f.followee_id
WHERE f.follower_id = #{userId}

  AND (f.created_at, f.followee_id) < (#{cursorFollowedAt}, #{cursorId})

ORDER BY f.created_at DESC, f.followee_id DESC
LIMIT #{limit}

